<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Order summary {{$order->order_number}}</title><style>body{font:14px Arial,sans-serif;margin:45px auto;max-width:820px;color:#213c30}h1{font-size:30px}table{width:100%;border-collapse:collapse;margin:30px 0}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}th{background:#e9f2ea}.total{text-align:right;font-weight:bold;font-size:22px}.muted{color:#66776d}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print order summary</button><h1>Wholesale Eco Products</h1><h2>Order summary · {{$order->order_number}}</h2><p>Business: {{$order->business_name}}<br>Date: {{$order->created_at->format('d M Y')}}<br>Payment status: {{$order->payment_status}}</p><p class="muted">Order summary only. This is not a VAT invoice.</p><table><tr><th>Product</th><th>SKU</th><th>Cases</th><th>Subtotal</th></tr>@foreach($order->items as $item)<tr><td>{{$item->product_name}}</td><td>{{$item->sku}}</td><td>{{$item->packs}}</td><td>£{{number_format($item->line_subtotal_pence/100,2)}}</td></tr>@endforeach</table><p class="total">Total £{{number_format($order->grand_total_pence/100,2)}}</p></body></html>
